export const getDeleteEventArenaLeaderboardEntryUrl = (eventId: string,
    params: DeleteEventArenaLeaderboardEntryParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/event-arena/${eventId}/leaderboard?${stringifiedParams}` : `/api/event-arena/${eventId}/leaderboard`
}

